import { test, expect } from '@playwright/test';

test.describe('Page Number Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should navigate to a specific page using page number input', async ({ page }) => {
    // Verify initial page content
    const pageNumberList = page.getByRole('region', { name: /page number/i });
    await expect(pageNumberList).toBeVisible();

    const pageCount = page.getByRole('heading', { name: /page count/i });
    await expect(pageCount).toBeVisible();

    const pageNumberInput = page.getByLabel('Page Number');
    await expect(pageNumberInput).toBeVisible();

    // Verify page navigation button is disabled initially
    const pageNavButton = page.getByRole('button', { name: /go to page/i });
    await expect(pageNavButton).toBeDisabled();

    // Set page number input to a valid value
    await pageNumberInput.fill('5');

    // Verify page number input is focused
    await expect(pageNumberInput).toHaveFocus();

    // Verify page navigation button is now enabled
    await expect(pageNavButton).not.toBeDisabled();

    // Click the page navigation button
    await pageNavButton.click();

    // Verify we are on the correct page
    const pageContent = page.getByText(/page 5/i);
    await expect(pageContent).toBeVisible();

    // Verify page number is displayed
    const pageNumberDisplay = page.getByText('Page 5');
    await expect(pageNumberDisplay).toBeVisible();

    // Verify page count is updated
    await expect(pageCount).toContainText('Page 5 of 10');

    // Verify page number input is cleared after navigation
    await expect(pageNumberInput).toHaveValue('');

    // Verify page navigation button is disabled again
    await expect(pageNavButton).toBeDisabled();
  });

  test('should handle invalid page number input and display error message', async ({ page }) => {
    // Verify initial page content
    const pageNumberList = page.getByRole('region', { name: /page number/i });
    await expect(pageNumberList).toBeVisible();

    const pageCount = page.getByRole('heading', { name: /page count/i });
    await expect(pageCount).toBeVisible();

    const pageNumberInput = page.getByLabel('Page Number');
    await expect(pageNumberInput).toBeVisible();

    // Verify page navigation button is disabled initially
    const pageNavButton = page.getByRole('button', { name: /go to page/i });
    await expect(pageNavButton).toBeDisabled();

    // Set page number input to an invalid value
    await pageNumberInput.fill('11');

    // Verify page number input is focused
    await expect(pageNumberInput).toHaveFocus();

    // Verify page navigation button is still disabled
    await expect(pageNavButton).toBeDisabled();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid page number/i);
    await expect(errorMessage).toBeVisible();

    // Verify page number input is still visible
    await expect(pageNumberInput).toBeVisible();

    // Verify page number is not displayed
    const pageNumberDisplay = page.getByText(/page 11/i);
    await expect(pageNumberDisplay).not.toBeVisible();

    // Verify page count is not updated
    await expect(pageCount).not.toContainText('Page 11 of 10');

    // Verify page navigation button is still disabled
    await expect(pageNavButton).toBeDisabled();
  });
});
